// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {StaxLPStaking} from "../src/StaxLPStaking.sol";

contract InvMutTest is Test {
    StaxLPStaking c;
    function setUp() public { c = new StaxLPStaking(address(this), address(this)); }
    function testRegression_property() public {
        vm.startPrank(address(this));
        _balances[address(this)] = 1000;
        _allowance[address(this)][address(c)] = 1000;
        vm.stopPrank();

        vm.prank(address(this));
        c.stake(100);

        address rewardToken = address(0xdead);
        vm.prank(address(this));
        c.addReward(rewardToken);

        assertTrue(c.totalSupply() == 100);
    }

    mapping(address => uint256) private _balances;
    mapping(address => mapping(address => uint256)) private _allowance;

    function balanceOf(address account) external view returns (uint256) {
        return _balances[account];
    }

    function transfer(address to, uint256 amount) external returns (bool) {
        _balances[msg.sender] -= amount;
        _balances[to] += amount;
        return true;
    }

    function allowance(address owner, address spender) external view returns (uint256) {
        return _allowance[owner][spender];
    }

    function approve(address spender, uint256 amount) external returns (bool) {
        _allowance[msg.sender][spender] = amount;
        return true;
    }

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        _allowance[from][msg.sender] -= amount;
        _balances[from] -= amount;
        _balances[to] += amount;
        return true;
    }

}
